@push('scripts')
<script>
const categoryBackendUrl = @json(rtrim(env('APP_URL', 'http://127.0.0.1:8000'), '/')); const categoryPath = document.getElementById('categoryPath'); const categoryFile = document.getElementById('categoryImageFile'); const categoryPreview = document.getElementById('categoryPreview'); const categoryPreviewImage = document.getElementById('categoryPreviewImage');
function categoryImageUrl(path) { const encoded = path.replace(/^\/+/, '').split('/').map(encodeURIComponent).join('/'); return /^https?:\/\//i.test(path) ? path : (/^\/?storage\//i.test(path) ? categoryBackendUrl + '/' + encoded : categoryBackendUrl + '/product-assets/' + encoded); }
function refreshCategoryPreview() { const path = categoryPath.value.trim(); if (!path) { categoryPreview.classList.remove('has-image'); categoryPreviewImage.removeAttribute('src'); return; } categoryPreviewImage.onload = () => categoryPreview.classList.add('has-image'); categoryPreviewImage.onerror = () => categoryPreview.classList.remove('has-image'); categoryPreviewImage.src = categoryImageUrl(path); }
categoryPath.addEventListener('input', refreshCategoryPreview); categoryFile.addEventListener('change', () => { const file = categoryFile.files[0]; if (!file) { refreshCategoryPreview(); return; } categoryPreviewImage.onload = () => categoryPreview.classList.add('has-image'); categoryPreviewImage.src = URL.createObjectURL(file); }); refreshCategoryPreview();
</script>
@endpush
